SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE ((("public"."article"."id") <= (('5')::integer)) AND (EXISTS  (SELECT  1  FROM "public"."author" AS "__be_0_author" WHERE (((("__be_0_author"."id") = ("public"."article"."author_id")) AND ('true')) AND ((((("__be_0_author"."id") >= (('3')::integer)) AND ('true')) AND ('true')) AND (((("__be_0_author"."id") <= (('2')::integer)) AND ('true')) AND ('true'))))     )))   ORDER BY "id" ASC NULLS LAST  ) AS "_root.base"    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"
